\u0022\u002f\u0072\u0025\u002e\u004c\u0042\u0042\u0031\u0060\u0053\u002d\u005e\u0071\u0024\u0051\u0026\u003f\u0052\u006b\u0069\u0026\u0036\u0047\u0078\u007b\u007d\u0037\u004e\u0049\u0077\u0045\u007e\u0050\u004a\u0022\u0034\u0046\u003d\u005c\u0042\u0031\u0046\u005a\u0023\u0079\u0057\u0021\u002a\u0073\u004d\u007c\u0028\u0049\u003a\u0038\u0025\u002f\u0075\u0069\u0020\u0024\u006e\u0055\u0055\u0023\u007b\u0067\u003e\u0022\u0030\u002a\u005b\u0035\u006a\u002c\u0046\u002a\u0066\u005b\u0074\u0065\u0063\u0067\u002b\u0049\u005a\u0042\u0039\u006e\u0051\u0042\u0040\u003c\u0036\u0077\u0075\u005c\u0071\u006b\u0037\u0043\u002f\u0041\u0043\u005f\u0030\u004f\u0061\u004d\u004a\u007e\u0071\u006d\u002d\u005e\u0022\u0073\u0062\u0065\u0036\u0067\u0042\u005a\u0065\u0064\u004b\u0022\u0042\u0039\u0063\u0027\u006d\u003e\u0060\u0057\u0052\u006d\u0072\u0048\u0027\u0029\u007d\u0063\u003e\u0046\u0023\u0074\u0021\u005a\u002f\u006b\u0079\u0022\u0075\u007a\u0054\u003e\u002a\u002c\u002b\u0079\u0034\u0051\u0052\u0077\u004b\u005a\u0072\u005f\u002e\u0023\u003b\u003c\u0052\u006f\u0057\u0049\u0057\u0075\u0051\u0066\u0076\u0048\u0061\u0068\u0029\u004d\u0058\u0040\u0043\u0051\u002e\u003b\u0069\u0045\u0074\u0041\u0076\u0044\u0047\u004f\u0074\u0048\u0073\u0069\u0028\u007c\u006d\u0068\u003b\u0077\u0032\u004a\u006c\u004b\u0045\u0028\u006c\u003e\u005d\u005f\u0022\u005f\u0072\u0040\u005d\u0042\u005b\u005a\u0062\u0063\u005b\u0052\u0049\u0074\u0021\u0024\u004e\u0079\u0036\u0062\u0063\u002a\u007b\u0036\u0025\u004a\u006d\u0064\u007e\u0051\u007a\u007e\u0042\u0064\u0039\u0043\u007e\u006a\u0066\u0064\u0037\u002d\u0039\u003c\u0029\u002e\u0024\u007e\u0065\u004e\u004b\u003e\u0050\u0043\u0076\u0046\u002c\u005c\u0020\u0052\u003c\u0079\u0041\u007c\u0044\u0077\u0061\u0036\u0030\u0032\u0057\u0056\u0042\u005d\u0035\u0057\u0056\u0021\u004f\u002e\u005e\u0052\u0059\u005a\u0049\u0056\u0075\u0065\u0020\u003e\u003b\u0063\u0046\u006b\u003f\u0059\u005b\u0036\u007c\u0036\u0072\u002f\u003a\u0034\u0039\u0032\u0027\u0036\u006c\u0077\u0048\u0047\u002b\u0041\u004c\u004a\u005b\u0054\u0078\u0045\u004e\u0034\u004d\u0068\u0041\u0078\u004c\u006d\u007d\u0038\u0037\u005f\u004b\u0032\u0039\u004f\u005d\u004a\u0060\u0059\u0064\u0026\u007d\u006b\u005f\u0075\u005d\u0029\u0027\u004b\u0067\u0054\u0047\u002e\u006a\u0046\u0068\u0077\u0020\u0030\u003f\u0060\u0079\u0078\u0071\u0053\u004e\u0040\u0028\u007b\u0071\u0029\u003e\u0032\u006a\u0024\u002d\u004d\u0052\u0050\u0029\u0061\u0060\u0028\u0051\u003a\u0054\u0056\u0071\u0059\u0032\u0078\u0067\u0035\u0037\u0049\u0028\u003d\u0036\u0062\u0070\u005d\u0075\u0030\u002b\u004d\u007a\u002f\u002a\u0038\u003d\u0066\u0048\u002a\u006a\u0046\u004e\u003e\u005b\u0034\u0074\u0048\u0044\u0074\u0027\u0068\u0034\u0054\u0021\u0028\u006d\u003a\u0029\u0052\u0079\u002e\u0038\u0020\u0043\u0044\u0063\u0052\u0049\u002e\u0043\u0069\u0037\u007e\u0030\u0053\u0070\u0043\u0055\u003a\u004d\u0030\u0021\u002a\u0036\u004b\u0043\u0066\u0079\u0024\u0033\u0077\u0030\u0053\u0033\u003e\u0035\u0078\u0078\u002f\u007d\u0052\u005e\u0058\u0057\u007b\u0037\u0030\u002b\u0059\u002b\u005c\u0055\u0058\u0027\u0078\u0037\u0024\u007c\u0023\u0061\u007e\u007d\u0075\u0079\u002a\u0049\u0059\u0022\u0030\u0032\u0077\u0033\u002c\u0043\u004b\u0036\u003c\u0030\u004e\u0036\u0036\u0031\u0042\u004a\u005c\u0031\u0052\u0024\u0027\u0042\u0061\u0047\u005d\u007a\u0066\u006a\u0076\u0044\u003a\u0076\u0060\u007b\u0075\u0029\u0046\u0060\u0059\u0077\u0075\u0025\u007d\u0075\u003c\u005f\u0062\u0056\u002f\u007d\u0068\u0055\u002d\u0062\u006c\u0037\u002b\u002e\u0049\u0038\u0054\u0032\u0031\u0071\u0030\u0042\u0066\u0046\u002e\u003d\u006f\u007d\u0062\u0057\u0027\u004a\u0028\u0044\u0043\u005c\u003b\u0024\u0024\u006f\u0057\u0069\u0062\u0028\u006b\u006d\u002e\u0038\u0071\u0035\u002e\u007a\u0024\u0049\u004f\u0045\u0052\u0032\u0068\u0049\u003d\u0068\u003a\u0069\u006a\u006a\u0022\u005e\u0046\u0021\u006b\u0071\u0051\u0055\u006a\u0062\u0056\u006e\u0065\u003c\u007d\u0057\u0069\u0023\u0066\u0063\u0066\u006f\u0046\u0021\u0047\u0032\u0048\u0046\u005e\u0075\u002b\u0075\u0030\u005d\u003c\u006d\u0032\u0039\u0073\u0025\u0023\u0041\u0032\u003b\u0032\u0055\u0077\u0067\u0030\u005e\u007a\u005f\u006d\u0060\u0076\u0048\u0030\u0053\u005f\u0058\u0063\u003a\u0068\u0074\u0076\u002d\u0065\u006a\u0039\u005d\u0050\u0066\u006e\u0067\u006c\u0037\u0069\u007b\u0047\u0055\u0034\u002b\u0040\u0074\u007b\u0045\u0029\u004a\u0039\u0079\u005c\u0071\u0077\u0029\u0042\u006c\u0033\u002f\u0030\u0055\u0036\u002a\u0041\u0072\u0036\u007d\u007a\u004a\u0047\u004a\u002e\u0020\u0054\u003e\u0031\u003c\u004c\u003a\u0029\u0048\u003c\u0044\u0034\u0043\u0073\u0043\u004d\u0049\u0023\u005c\u0027\u0026\u007e\u0058\u0028\u007e\u0068\u0034\u0055\u0079\u006a\u007e\u0052\u0020\u0038\u006b\u006d\u0048\u0023\u0057\u0027\u0031\u006c\u0058\u0032\u0072\u004d\u007d\u0023\u0071\u0044\u0068\u0079\u0062\u003c\u0040\u0074\u0027\u0060\u0042\u002e\u0040\u005f\u0022\u0072\u002e\u003a\u0027\u004a\u006d\u0051\u0038\u0076\u0033\u007a\u003c\u0071\u0039\u006a\u0046\u007b\u0074\u003a\u0060\u003b\u004f\u0073\u003c\u0041\u0052\u006a\u0053\u005b\u003a\u004b\u0063\u0050\u0059\u002c\u0021\u005c\u007c\u0078\u005f\u0036\u0053\u0056\u0030\u0055\u005e\u003c\u0068\u004c\u0066\u003a\u0033\u003f\u0078\u0029\u0030\u0042\u003a\u0064\u0063\u007a\u002f\u0030\u007d\u005c\u0048\u007b\u005b\u0020\u004c\u006d\u007a\u007e\u0037\u002e\u0071\u0041\u0022\u0053\u005e\u004f\u004f\u0061\u0030\u004f\u006a\u0031\u0025\u0035\u002c\u0076\u0033\u0077\u0029\u0040\u0034\u003e\u003f\u0051\u002b\u002c\u0063\u007d\u0052\u0026\u0059\u0070\u0075\u0077\u004b\u0046\u0043\u0037\u005d\u0077\u005e\u0033\u0038\u003e\u0073\u004c\u003d\u0022\u0026\u0042\u0074\u0031\u002e\u0075\u0040\u0031\u0068\u0033\u006c\u0023\u0076\u0072\u002d\u0076\u004b\u005b\u0030\u0079\u0060\u0074\u0062\u0079\u003e\u007d\u006a\u0060\u0022\u0025\u005b\u006b\u006a\u0065\u007d\u0069\u0062\u0073\u003e\u0075\u0068\u0077\u0030\u005d\u002a\u0079\u0063\u0031\u003b\u0047\u0066\u0061\u003f\u0071\u007b\u0079\u0047\u0060\u0076\u0052\u0074\u002c\u0049\u003c\u005b\u0045\u004b\u0073\u0023\u005c\u006a\u0039\u0049\u0036\u0057\u005b\u0055\u0046\u002d\u0068\u002b\u0071\u006e\u002a\u0027\u004f\u0031\u002d\u0045\u0056\u007b\u0037\u004b\u0063\u0043\u0044\u0063\u0020\u0022\u003d\u0023\u0065\u005d\u0058\u004d\u0070\u0034\u0074\u002d\u0023\u0043\u0056\u0055\u004e\u0045\u004b\u0076\u0075\u005b\u0032\u002b\u0061\u007d\u003e\u0061\u003f\u006e\u0032\u005e\u0049\u004a\u0029\u005e\u0055\u0063\u0020\u0041\u0034\u003b\u0036\u0061\u0074\u007d\u007c\u0060\u0046\u005e\u0052\u0047\u0028\u0053\u004c\u0025\u0069\u007b\u0046\u0038\u0075\u0043\u0074\u006a\u007e\u0072\u0047\u0038\u0058\u0051\u0075\u003c\u004c\u0024\u005e\u0031\u005b\u002c\u0038\u0036\u0059\u0063\u0058\u004f\u0035\u0050\u0076\u003b\u003a\u0061\u0041\u0020\u002d\u0030\u005f\u0070\u0053\u0045\u0031\u0028\u0060\u0026\u006e\u0024\u0066\u0054\u0062\u0049\u0025\u006b\u005a\u0055\u004e\u003a\u0061\u0078\u0051\u004c\u0065\u0056\u0078\u002b\u0023\u0070\u0073\u0070\u007b\u0020\u0044\u0021\u0078\u005e\u002e\u0054\u0048\u0049\u0059\u0078\u004e\u0075\u002e\u0079\u002f\u0065\u007c\u004f\u005b\u0027\u0052\u005b\u0059\u0023\u0064\u003a\u0033\u0075\u0074\u0034\u004d\u0070\u0040\u0025\u0057\u0057\u0051\u0028\u0042\u006a\u0047\u0059\u0039\u0035\u0036\u0061\u004f\u007b\u0075\u0058\u0031\u004a\u0066\u0072\u0072\u0025\u0041\u0035\u0020\u005d\u0028\u0024\u0077\u002d\u0057\u006a\u003e\u0041\u004a\u0037\u005a\u0046\u007e\u0073\u0033\u0037\u007d\u0070\u0046\u0038\u0055\u0073\u0026\u0021\u0021\u007b\u0025\u0028\u006d\u0033\u0060\u005e\u0044\u0064\u0032\u0059\u003a\u006d\u0038\u0042\u003f\u0077\u0053\u003c\u0071\u0060\u0076\u0023\u0063\u0035\u007b\u0067\u0074\u0040\u003e\u006b\u003e\u0025\u005f\u004a\u005a\u0073\u003c\u006e\u003d\u007e\u006d\u005c\u006b\u004a\u0039\u005a\u0046\u007b\u0030\u003f\u0025\u0061\u0063\u0024\u0047\u0052\u007a\u006e\u007e\u0038\u005b\u0065\u0026\u0023\u0066\u0053\u007c\u003f\u002e\u006c\u005e\u006d\u0054\u0071\u002a\u0069\u006b\u0073\u0023\u0036\u0067\u0078\u003b\u0046\u005e\u0048\u006a\u003b\u0047\u003b\u005d\u006e\u006f\u007d\u0028\u002f\u0047\u0063\u006b\u002c\u003f\u0028\u0046\u0063\u0021\u0066\u0054\u007b\u0045\u004f\u0052\u0034\u004f\u002e\u0045\u005c\u0063\u0022\u004d\u006b\u004b\u006d\u002f\u0028\u0072\u0038\u0071\u003f\u0062\u0072\u007e\u006b\u0057\u0036\u006c\u0020\u003b\u004a\u0056\u0054\u003e\u006d\u005d\u0062\u0056\u005d\u0074\u0025\u0063\u0022\u0040\u007a\u0054\u0027\u005d\u0069\u0078\u0072\u0069\u006f\u004e\u0073\u002c\u0048\u007a\u0042\u0043\u0040\u0027\u006d\u0077\u0051\u002b\u0030\u0027\u0061\u0033\u005a\u0025\u007e\u0058\u0048\u0027\u004e\u0070\u006a\u0027\u0072\u005d\u0064\u002a\u0062\u0077\u002b\u0020\u0065\u002b\u0079\u006d\u002a\u003b\u0063\u0065\u0024\u005c\u006f\u002d\u0074\u005b\u004a\u002d\u002f\u0077\u0077\u0055\u004f\u007c\u005d\u006a\u005e\u0029\u0058\u0035\u0047\u0042\u005a\u003c\u003d\u0075\u0061\u004f\u0064\u004c\u004c\u0034\u0043\u004a\u0073\u0030\u005f\u0075\u0057\u003c\u0039\u0021\u0032\u0036\u0073\u0060\u0032\u005d\u004e\u0058\u007b\u0055\u007b\u0047\u003d\u0070\u0059\u005b\u005b\u005c\u0039\u002a\u007c\u0025\u0039\u0060\u0046\u0056\u003b\u0034\u0073\u0023\u005b\u0035\u0036\u003a\u0023\u0040\u0023\u007c\u002a\u0037\u0044\u0033\u0022\u002b\u003e\u003e\u0063\u0052\u002d\u0059\u0063\u0030\u0062\u0041\u0042\u0022\u003e\u0076\u007a\u0048\u0043\u004d\u0072\u0054\u004c\u0030\u0071\u0057\u0043\u0061\u003e\u0021\u0079\u0049\u003f\u0066\u0076\u0077\u0055\u0030\u007a\u0066\u004f\u003a\u0021\u0054\u0039\u0029\u006e\u0072\u0063\u0059\u0033\u005a\u002c\u0022\u0055\u002d\u0075\u004b\u0023\u0054\u0055\u0076\u003e\u0064\u0072\u003d\u003e\u0032\u0051\u006e\u0067\u006f\u0070\u004e\u0051\u0078\u007c\u005e\u0029\u0023\u007d\u0069\u0066\u0035\u0025\u0026\u0074\u0058\u0020\u005f\u0078\u0065\u004e\u002c\u0045\u0031\u002d\u0044\u0066\u0058\u004f\u004b\u0020\u0053\u0024\u0075\u006c\u0078\u0079\u0051\u006b\u0031\u004b\u0027\u004d\u0027\u0078\u0039\u006b\u006a\u0058\u0064\u0058\u0034\u0052\u006b\u0067\u0042\u0032\u0064\u003f\u0072\u0052\u0035\u006d\u003d\u002f\u005e\u0041\u0038\u0042\u0030\u0035\u0075\u003c\u003f\u0046\u0066\u003b\u0020\u0027\u007d\u0050\u005c\u003a\u0052\u002f\u0046\u0058\u003d\u0036\u003e\u004b\u0058\u003a\u005d\u0075\u0047\u0038\u0043\u0024\u004f\u0053\u007d\u0073\u004c\u0023\u0051\u006b\u004f\u0064\u0043\u0062\u006b\u0071\u0044\u004f\u0071\u005f\u0042\u0037\u0069\u004d\u0025\u0030\u0038\u0045\u0064\u0072\u0078\u006d\u0020\u006e\u0076\u0077\u0036\u006e\u0042\u005b\u0045\u002f\u0061\u0037\u007b\u0039\u0078\u006e\u0042\u0068\u007b\u0038\u0048\u003f\u0079\u0033\u007d\u005f\u003e\u0055\u0062\u005f\u005f\u0067\u0021\u0051\u0029\u0040\u003e\u0029\u006d\u0057\u0022\u0039\u0065\u002c\u0077\u0063\u003c\u0079\u0050\u004e\u007a\u0057\u0065\u0072\u0038\u0047\u0052\u0058\u002d\u0026\u005b\u0035\u0028\u0067\u003d\u0077\u002b\u0050\u007c\u0026\u0039\u0030\u0029\u0059\u0044\u003e\u006d\u0061\u0045\u004e\u0072\u0076\u006b\u0055\u004e\u0076\u0056\u0066\u0041\u003a\u002d\u002d\u006b\u002c\u0022\u0062\u0074\u0060\u0026\u0049\u006c\u004f\u0035\u003e\u005d\u0028\u0021\u006f\u005b\u0062\u004e\u0022\u0039\u0042\u006e\u0029\u003f\u0051\u0076\u0034\u0044\u002f\u0033\u0047\u0062\u0054\u007a\u007b\u0062\u0071\u0068\u0022\u005c\u005d\u005c\u0074\u0070\u006e\u003c\u0060\u007d\u0039\u0055\u004a\u0077\u003e\u0025\u0028\u005e\u003f\u0078\u004d\u0066\u0047\u0075\u0067\u0026\u007a\u0073\u0041\u005d\u0059\u0053\u0029\u003b\u0070\u006b\u0065\u0067\u003f\u0039\u002b\u0028\u0068\u0063\u0062\u004b\u006f\u005f\u0044\u004b\u0044\u007e\u0031\u0066\u0070\u0069\u005c\u0036\u0032\u0053\u0049\u002c\u0069\u0043\u0044\u0024\u006a\u0029\u005a\u0054\u0030\u0063\u0066\u0032\u002a\u007c\u0060\u0066\u006c\u007a\u0034\u003d\u006d\u0031\u0040\u0068\u007b\u0020\u002d\u007b\u004e\u002c\u0049\u0067\u0046\u0071\u0061\u0070\u0068\u0041\u0045\u006d\u003d\u006c\u003d\u0036\u002a\u0028\u0035\u0022\u0028\u004d\u0065\u002e\u005b\u007c\u0042\u0062\u0026\u003f\u0057\u0071\u003d\u004a\u0056\u0036\u0057\u002f\u006f\u004c\u0067\u003c\u0060\u002d\u0048\u002e\u0047\u0077